// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    address asserter;

    function setUp() public {
        __InvMutHandleStub stub = new __InvMutHandleStub();
        asserter = address(stub);
        c = new BaseEscalationManager(asserter);
    }

    function testFuzz_property(bytes32 identifier, uint256 time, uint256 seed) public {
        // Build a wide, admissible ancillary payload (large enough that the
        // LOG3 emission of the recorded request costs thousands of gas).
        bytes memory ancillaryData = new bytes(1000);
        for (uint256 i = 0; i < 31; i++) {
            bytes32 chunk = keccak256(abi.encode(identifier, time, seed, i));
            assembly {
                mstore(add(add(ancillaryData, 0x20), mul(i, 32)), chunk)
            }
        }

        // Calldata identical for both the no-op probe and the real call.
        bytes memory payload = abi.encodeWithSelector(c.requestPrice.selector, identifier, time, ancillaryData);

        // Baseline: same calldata sent to a plain receiver that does nothing.
        vm.prank(asserter);
        uint256 g0 = gasleft();
        (bool okStub, ) = asserter.call(payload);
        uint256 stubUsed = g0 - gasleft();

        // Warm up c (also warms the optimisticAsserter SLOAD slot).
        vm.prank(asserter);
        c.requestPrice(identifier, time, ancillaryData);

        // Measured call to c.
        vm.prank(asserter);
        uint256 g1 = gasleft();
        c.requestPrice(identifier, time, ancillaryData);
        uint256 cUsed = g1 - gasleft();

        // Rule: a requestPrice call from the asserter must record the request,
        // costing far more overhead than a no-op receiver with the same calldata.
        assertTrue(okStub && (cUsed - stubUsed) > 4000);
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
